/// Render a horizontal gain reduction meter
/// Uses render_gradient_meter for consistent styling
pub fn render_gr_meter(
    d: &Ds,
    gain_reduction_db: f64, // Should be negative or 0
    max_db: f64,            // e.g., -30.0 (max gain reduction to display)
    theme: &Theme,
) -> impl IntoElement {
    let gr_abs = gain_reduction_db.abs();
    let tick_config = TickConfig::gain_reduction(max_db);

    // Calculate fill ratio using tick config scale
    let fill_ratio = tick_config.value_to_position(gr_abs);

    // Color gradient: green -> yellow -> red based on amount
    let color = if gr_abs < 3.0 {
        theme.meter_normal // Green
    } else if gr_abs < 10.0 {
        theme.meter_warning // Yellow/Orange
    } else {
        theme.meter_clip // Red
    };

    div()
        .flex()
        .flex_col()
        .gap(d.grid)
        .w_full()
        // Header row with label and value
        .child(
            div()
                .flex()
                .justify_between()
                .items_center()
                .child(
                    div()
                        .text_size(d.text_xs)
                        .font_weight(FontWeight::SEMIBOLD)
                        .text_color(theme.text_secondary)
                        .child("Gain Reduction"),
                )
                .child(
                    div()
                        .min_w(rems(4.375))
                        .px(d.pad_y)
                        .py(d.pad_y_half)
                        .rounded(d.r_md)
                        .bg(theme.surface)
                        .text_size(d.text_xs)
                        .font_weight(FontWeight::BOLD)
                        .text_color(color)
                        .text_align(TextAlign::Right)
                        .child(format!("-{:.1} dB", gr_abs)),
                ),
        )
        // Meter bar (full width)
        .child(
            div()
                .h(rems(0.75))
                .w_full()
                .bg(theme.background)
                .rounded(d.r_md)
                .border_1()
                .border_color(theme.border)
                .overflow_hidden()
                .child(
                    div()
                        .h_full()
                        .w(relative(fill_ratio))
                        .bg(color)
                        .rounded_l_md(),
                ),
        )
        // Tick marks (full width)
        .child(render_tick_row(&tick_config, 0.0, 0.0))
        // Legend (full width) - show as negative dB values (0, -10, -20, -30)
        .child(
            div()
                .flex()
                .justify_between()
                .text_size(d.text_xs)
                .text_color(theme.text_muted)
                .children(tick_config.major_values.iter().map(|v| {
                    let label = if *v == 0.0 {
                        "0".to_string()
                    } else {
                        format!("-{:.0}", v)
                    };
                    div().child(label)
                })),
        )
}

/// Render a vertical peak meter with ceiling indicator
pub fn render_peak_meter(d: &Ds, peak_db: f64, ceiling_db: f64, theme: &Theme) -> impl IntoElement {
    let min_db = -60.0;
    let normalized = ((peak_db - min_db) / (0.0 - min_db)).clamp(0.0, 1.0) as f32;
    let ceiling_normalized = ((ceiling_db - min_db) / (0.0 - min_db)).clamp(0.0, 1.0) as f32;

    // Color based on level
    let color = if peak_db > ceiling_db - 3.0 {
        theme.meter_clip // Red - clipping or near ceiling
    } else if peak_db > -12.0 {
        theme.meter_warning // Yellow - moderate
    } else {
        theme.meter_normal // Green - safe
    };

    div()
        .flex()
        .flex_col()
        .items_center()
        .gap(d.grid)
        // Label
        .child(
            div()
                .text_size(d.text_xs)
                .font_weight(FontWeight::SEMIBOLD)
                .text_color(theme.text_secondary)
                .child("Peak"),
        )
        // Meter
        .child(
            div()
                .w(rems(1.25))
                .h(rems(5.0))
                .bg(theme.background)
                .rounded(d.r_md)
                .border_1()
                .border_color(theme.border)
                .relative()
                .overflow_hidden()
                // Level bar
                .child(
                    div()
                        .absolute()
                        .bottom_0()
                        .left_0()
                        .right_0()
                        .h(relative(normalized))
                        .bg(color),
                )
                // Ceiling marker
                .child(
                    div()
                        .absolute()
                        .left_0()
                        .right_0()
                        .bottom(relative(ceiling_normalized))
                        // intentional: 2px ceiling marker line — visual indicator, not spacing
                        .h(px(2.0))
                        .bg(theme.meter_clip),
                ),
        )
        // Value
        .child(
            div()
                .text_size(d.text_xs)
                .font_weight(FontWeight::BOLD)
                .text_color(color)
                .child(if peak_db <= min_db {
                    "-∞".to_string()
                } else {
                    format!("{:.1}", peak_db)
                }),
        )
}

/// Render a meter with gradient coloring (green, yellow at top, red at clip)
/// Optional peak_ratio shows a peak hold indicator line
pub fn render_gradient_meter(
    d: &Ds,
    fill_ratio: f32,
    yellow_threshold: f32,
    red_threshold: f32,
    peak_ratio: Option<f32>,
    channel_name: String,
    theme: &Theme,
) -> impl IntoElement {
    // Calculate segment heights
    let green_height = fill_ratio.min(yellow_threshold);
    let yellow_height = if fill_ratio > yellow_threshold {
        (fill_ratio - yellow_threshold).min(red_threshold - yellow_threshold)
    } else {
        0.0
    };
    let red_height = if fill_ratio > red_threshold {
        fill_ratio - red_threshold
    } else {
        0.0
    };

    let theme_c = theme.clone();
    let peak_color = theme.meter_colors.peak;
    div()
        .flex()
        .flex_col()
        .items_center()
        .flex_1()
        // Meter bar container
        .child(
            div()
                .w(rems(1.0))
                .flex_1()
                .min_h(rems(11.25))
                .bg(theme_c.background)
                .rounded(d.r_sm)
                .overflow_hidden()
                .relative()
                // Green segment (base)
                .child(
                    div()
                        .absolute()
                        .bottom_0()
                        .left_0()
                        .right_0()
                        .h(gpui::Length::Definite(gpui::DefiniteLength::Fraction(
                            green_height,
                        )))
                        .bg(theme_c.meter_normal),
                )
                // Yellow segment (above green)
                .when(yellow_height > 0.001, |el| {
                    el.child(
                        div()
                            .absolute()
                            .left_0()
                            .right_0()
                            .bottom(gpui::Length::Definite(gpui::DefiniteLength::Fraction(
                                yellow_threshold,
                            )))
                            .h(gpui::Length::Definite(gpui::DefiniteLength::Fraction(
                                yellow_height,
                            )))
                            .bg(theme_c.meter_warning),
                    )
                })
                // Red segment (above yellow)
                .when(red_height > 0.001, |el| {
                    el.child(
                        div()
                            .absolute()
                            .left_0()
                            .right_0()
                            .bottom(gpui::Length::Definite(gpui::DefiniteLength::Fraction(
                                red_threshold,
                            )))
                            .h(gpui::Length::Definite(gpui::DefiniteLength::Fraction(
                                red_height,
                            )))
                            .bg(theme_c.meter_clip),
                    )
                })
                // Peak hold indicator (horizontal line)
                .when(peak_ratio.is_some_and(|p| p > 0.001), |el| {
                    let peak_pos = peak_ratio.unwrap_or(0.0);
                    el.child(
                        div()
                            .absolute()
                            .left_0()
                            .right_0()
                            .bottom(gpui::Length::Definite(gpui::DefiniteLength::Fraction(
                                peak_pos,
                            )))
                            // intentional: 2px peak-hold indicator line — visual, not spacing
                            .h(px(2.0))
                            .bg(peak_color),
                    )
                }),
        )
        // Channel name
        .child(
            div()
                .text_size(d.text_xs)
                .text_color(theme.text_muted)
                .mt(d.grid)
                .child(channel_name),
        )
}

/// Render LUFS display with True Peak bars at top (standalone function)
pub fn render_lufs_with_true_peak(
    d: &Ds,
    loudness: Option<&sotf_audio_player::LoudnessData>,
    theme: &Theme,
) -> impl IntoElement {
    let (
        integrated_lufs,
        shortterm_lufs,
        momentary_lufs,
        true_peak_left,
        true_peak_right,
        stereo_width,
        peak_spread,
        channel_count,
    ) = if let Some(l) = loudness {
        let tp_left = l.true_peaks_dbtp.first().copied().unwrap_or(-60.0);
        let tp_right = l.true_peaks_dbtp.get(1).copied().unwrap_or(tp_left);
        // Stereo width derived from correlation: +1 = mono (0), 0 = uncorrelated (0.5), -1 = out of phase (1)
        let width = l
            .correlation_lr
            .map(|c| ((1.0 - c) / 2.0).clamp(0.0, 1.0))
            .unwrap_or(0.5);
        let peak_spread = peak_spread_db(&l.true_peaks_dbtp);
        let channel_count = l.true_peaks_dbtp.len();
        (
            l.integrated_lufs,
            l.shortterm_lufs,
            l.momentary_lufs,
            tp_left,
            tp_right,
            width,
            peak_spread,
            channel_count,
        )
    } else {
        (-60.0, -60.0, -60.0, -60.0, -60.0, 0.5, 0.0, 0)
    };

    let meter_theme = MeterTheme::from_theme(theme);

    div()
        .flex()
        .flex_col()
        // Fill the available width so the bars (each `flex_1` inside
        // render_meter_bar) actually grow when the meters panel is wide.
        // Without this, the outer flex_col sizes to content and the bars
        // collapse to whatever flex_1 of the intrinsic-width parent works
        // out to — leaving a wide empty band on the right of the panel.
        .w_full()
        .gap(d.section)
        .p(d.pad_x)
        // True Peak section (on top)
        .child({
            // Use TickConfig preset for True Peak (quadratic scale from -60 to +6)
            let tick_config = TickConfig::true_peak();

            div()
                .flex()
                .flex_col()
                .gap(d.gap)
                .child(
                    div()
                        .text_size(d.text_sm)
                        .font_weight(FontWeight::SEMIBOLD)
                        .text_color(theme.text_primary)
                        .mb(d.grid)
                        .child("True Peak"),
                )
                // Left channel bar (uses same scale as ticks)
                .child(PlayerView::render_meter_bar(
                    d,
                    "L",
                    true_peak_left,
                    &tick_config,
                    &meter_theme,
                ))
                // Right channel bar (uses same scale as ticks)
                .child(PlayerView::render_meter_bar(
                    d,
                    "R",
                    true_peak_right,
                    &tick_config,
                    &meter_theme,
                ))
                // Tick marks (aligned with bar using same flex layout)
                .child(render_tick_row(
                    &tick_config,
                    meter_theme.label_width,
                    meter_theme.value_width,
                ))
                // True Peak legend (same flex layout as bar and ticks)
                .child(
                    div()
                        .flex()
                        // intentional: pixel-exact meter divider — do not scale
                        .gap(px(1.0))
                        // Label spacer
                        .child(div().w(px(meter_theme.label_width)))
                        // Legend area (flex-1, justify_between for labels)
                        .child(
                            div()
                                .flex_1()
                                .flex()
                                .justify_between()
                                .text_size(d.text_xs)
                                .text_color(meter_theme.color_text_muted)
                                .children(tick_config.major_values.iter().map(|db| {
                                    let label = if *db > 0.0 {
                                        format!("+{}", *db as i32)
                                    } else {
                                        format!("{}", *db as i32)
                                    };
                                    div().child(label)
                                })),
                        )
                        // Value spacer
                        .child(div().w(px(meter_theme.value_width))),
                )
        })
        // LUFS section (below)
        .child({
            // Use TickConfig preset for LUFS (quadratic scale from -60 to 0)
            let tick_config = TickConfig::lufs();

            div()
                .flex()
                .flex_col()
                .gap(d.gap)
                .child(
                    div()
                        .text_size(d.text_sm)
                        .font_weight(FontWeight::SEMIBOLD)
                        .text_color(theme.text_primary)
                        .mb(d.grid)
                        .child("LUFS"),
                )
                // Integrated LUFS (uses same scale as ticks)
                .child(PlayerView::render_meter_bar(
                    d,
                    "I",
                    integrated_lufs,
                    &tick_config,
                    &meter_theme,
                ))
                // Short-term LUFS (uses same scale as ticks)
                .child(PlayerView::render_meter_bar(
                    d,
                    "S",
                    shortterm_lufs,
                    &tick_config,
                    &meter_theme,
                ))
                // Momentary LUFS (uses same scale as ticks)
                .child(PlayerView::render_meter_bar(
                    d,
                    "M",
                    momentary_lufs,
                    &tick_config,
                    &meter_theme,
                ))
                // Tick marks (aligned with bar using same flex layout)
                .child(render_tick_row(
                    &tick_config,
                    meter_theme.label_width,
                    meter_theme.value_width,
                ))
                // LUFS legend (same flex layout as bar and ticks)
                .child(
                    div()
                        .flex()
                        .gap(spacing::SM)
                        // Label spacer
                        .child(div().w(px(meter_theme.label_width)))
                        // Legend area (flex-1, justify_between for labels)
                        .child(
                            div()
                                .flex_1()
                                .flex()
                                .justify_between()
                                .text_size(d.text_xs)
                                .text_color(meter_theme.color_text_muted)
                                .child(div().child("-60"))
                                .child(div().child("-30"))
                                .child(div().child("-10"))
                                .child(div().child("0")),
                        )
                        // Value spacer
                        .child(div().w(px(meter_theme.value_width))),
                )
        })
        // Stereo Width / Peak Spread section
        .child({
            if should_use_peak_spread(channel_count) {
                let tick_config = TickConfig::peak_spread();

                div()
                    .flex()
                    .flex_col()
                    .gap(d.gap)
                    .child(
                        div()
                            .text_size(d.text_sm)
                            .font_weight(FontWeight::SEMIBOLD)
                            .text_color(theme.text_primary)
                            .mb(d.grid)
                            .child("Peak Spread"),
                    )
                    .child(PlayerView::render_peak_spread_bar(
                        d,
                        peak_spread,
                        &tick_config,
                        &meter_theme,
                    ))
                    .child(render_tick_row(
                        &tick_config,
                        meter_theme.label_width,
                        meter_theme.value_width,
                    ))
                    .child(
                        div()
                            .flex()
                            .gap(spacing::SM)
                            .child(div().w(px(meter_theme.label_width)))
                            .child(
                                div()
                                    .flex_1()
                                    .flex()
                                    .justify_between()
                                    .text_size(d.text_xs)
                                    .text_color(meter_theme.color_text_muted)
                                    .child(div().child("Even"))
                                    .child(div().child("6 dB"))
                                    .child(div().child("12 dB"))
                                    .child(div().child("24+")),
                            )
                            .child(div().w(px(meter_theme.value_width))),
                    )
                    .into_any_element()
            } else {
                let tick_config = TickConfig::stereo_width();

                div()
                    .flex()
                    .flex_col()
                    .gap(d.gap)
                    .child(
                        div()
                            .text_size(d.text_sm)
                            .font_weight(FontWeight::SEMIBOLD)
                            .text_color(theme.text_primary)
                            .mb(d.grid)
                            .child("Stereo Width"),
                    )
                    .child(PlayerView::render_width_bar(
                        d,
                        stereo_width,
                        &tick_config,
                        &meter_theme,
                    ))
                    .child(render_tick_row(
                        &tick_config,
                        meter_theme.label_width,
                        meter_theme.value_width,
                    ))
                    .child(
                        div()
                            .flex()
                            .gap(spacing::SM)
                            .child(div().w(px(meter_theme.label_width)))
                            .child(
                                div()
                                    .flex_1()
                                    .flex()
                                    .justify_between()
                                    .text_size(d.text_xs)
                                    .text_color(meter_theme.color_text_muted)
                                    .child(div().child("Mono"))
                                    .child(div().child("50%"))
                                    .child(div().child("Wide")),
                            )
                            .child(div().w(px(meter_theme.value_width))),
                    )
                    .into_any_element()
            }
        })
}

impl PlayerView {
    /// Render vertical dB legend
    pub fn render_vertical_legend(
        &self,
        d: &Ds,
        theme: &Theme,
        align_right: bool,
    ) -> impl IntoElement {
        let ticks = [0, -6, -12, -18, -24, -30, -40, -50, -60];
        let theme = theme.clone();
        let text_xs = d.text_xs;
        let grid = d.grid;

        div()
            .flex()
            .flex_col()
            .h_full()
            .min_h(rems(17.5))
            .p_0p5() // Match meter group padding
            // Outer container (matches meters_row flex_1 h_full)
            .child(
                div()
                    .flex()
                    .flex_col()
                    .flex_1()
                    .min_h(rems(12.5))
                    // Ticks area (matches meter_bar flex_1).
                    // Width is wide enough to fit a 3-char dB label
                    // ("-60") + tick + a small gap; both legends use the
                    // same width so the meter group between them sits at
                    // the panel's true horizontal centre. Narrower
                    // widths cause labels to overflow on the left
                    // legend (clipped or pushed out of the panel) while
                    // the right legend's labels overflow into adjacent
                    // empty space — visible asymmetry.
                    .child(
                        div()
                            .relative()
                            .flex_1()
                            .min_h(rems(11.25))
                            .w(rems(2.25))
                            .overflow_hidden()
                            .children(ticks.into_iter().map(move |db| {
                                let pos = db_to_position(db as f64);
                                // Use top positioning: top = (1 - pos), then offset by half line height
                                let top_fraction = 1.0 - pos;

                                // Adjust label offset for edge labels to keep them visible:
                                // - Top label (0 dB): move label down
                                // - Bottom label (-60 dB): move label up
                                // - Other labels: no additional offset
                                let label_offset = if db == 0 {
                                    px(6.0) // Top: move label down
                                } else if db == -60 {
                                    px(-6.0) // Bottom: move label up
                                } else {
                                    px(0.0) // No additional offset
                                };

                                let label = div()
                                    .text_size(rems(0.5625))
                                    .text_color(theme.text_muted)
                                    .mt(label_offset)
                                    .child(format!("{}", db));

                                let tick = div().w(px(4.0)).h(px(1.0)).bg(theme.border);

                                let container = div()
                                    .absolute()
                                    .left_0()
                                    .right_0()
                                    .top(gpui::Length::Definite(gpui::DefiniteLength::Fraction(
                                        top_fraction,
                                    )))
                                    // Offset by half line height (~6px for 9px text) to center tick on position
                                    .mt(px(-6.0))
                                    .flex()
                                    .items_center()
                                    .justify_between();

                                if align_right {
                                    // Legend on right: tick → label (tick points toward meter on left)
                                    container.child(tick).child(label)
                                } else {
                                    // Legend on left: label → tick (tick points toward meter on right)
                                    container.child(label).child(tick)
                                }
                            })),
                    )
                    // Spacer for Channel Name (matches render_gradient_meter channel name)
                    .child(
                        div().text_size(text_xs).mt(grid).opacity(0.0).child("X"), // Dummy text to match height
                    ),
            )
            // Spacer (matches MSD buttons height and margin)
            .child(
                div()
                    .flex()
                    .flex_col()
                    // intentional: 1px divider mirrors real MSD column below — do not scale
                    .gap(px(1.0))
                    .mt(grid)
                    .items_center()
                    .justify_center()
                    .opacity(0.0) // Invisible, just for spacing
                    .child(
                        div()
                            .px(spacing::XS)
                            .py(spacing::XS)
                            .text_size(text_xs)
                            .child("M"),
                    )
                    .child(
                        div()
                            .px(spacing::XS)
                            .py(spacing::XS)
                            .text_size(text_xs)
                            .child("S"),
                    )
                    .child(
                        div()
                            .px(spacing::XS)
                            .py(spacing::XS)
                            .text_size(text_xs)
                            .child("D"),
                    ),
            )
    }

    /// Render a single meter group with M/S/D buttons below the channels
    pub fn render_meter_group(
        &self,
        group: &ChannelGroup,
        group_idx: usize,
        _is_selected: bool,
        loudness: Option<&sotf_audio_player::LoudnessData>,
        peak_hold: &[f64],
        theme: &Theme,
        cx: &mut Context<Self>,
    ) -> impl IntoElement {
        let d = Ds::from_cx(cx);
        let muted = group.muted;
        let soloed = group.soloed;
        let dimmed = group.dimmed;

        // Pre-compute channel data to avoid closure issues with cx
        let channel_data: Vec<_> = group
            .channels
            .iter()
            .map(|channel| {
                let peak = loudness
                    .and_then(|l| l.channel_peaks.get(channel.index))
                    .copied()
                    .unwrap_or(0.0);

                let peak_db = if peak > 0.0001 {
                    20.0 * peak.log10()
                } else {
                    -60.0
                };

                // Get peak hold value for this channel
                let peak_hold_value = peak_hold.get(channel.index).copied().unwrap_or(0.0);
                let peak_hold_db = if peak_hold_value > 0.0001 {
                    20.0 * peak_hold_value.log10()
                } else {
                    -60.0
                };
                let peak_hold_ratio = if peak_hold_value > 0.0001 {
                    Some(db_to_position(peak_hold_db))
                } else {
                    None
                };

                let fill_ratio = db_to_position(peak_db);
                let yellow_threshold = db_to_position(-6.0);
                let red_threshold = db_to_position(-1.0);

                (
                    fill_ratio,
                    yellow_threshold,
                    red_threshold,
                    peak_hold_ratio,
                    channel.name.clone(),
                )
            })
            .collect();

        let theme_c = theme.clone();
        div()
            .flex()
            .flex_col()
            .h_full()
            .min_h(rems(17.5))
            .p_0p5()
            // Removed rounded_md and selection background logic
            .bg(theme_c.background_secondary)
            // Channel meters
            .child(div().flex().gap_px().flex_1().min_h(rems(12.5)).children(
                channel_data.into_iter().map(
                    |(fill_ratio, yellow_threshold, red_threshold, peak_hold_ratio, name)| {
                        render_gradient_meter(
                            &d,
                            fill_ratio,
                            yellow_threshold,
                            red_threshold,
                            peak_hold_ratio,
                            name,
                            theme,
                        )
                    },
                ),
            ))
            // M/S/D buttons vertical column below meters, centered
            .child(
                div()
                    .flex()
                    .flex_col()
                    // intentional: pixel-exact MSD divider — do not scale
                    .gap(px(1.0))
                    .mt(d.grid)
                    .items_center()
                    .justify_center()
                    .child(self.render_msd_button(
                        "M",
                        muted,
                        theme.button_mute_active,
                        group_idx,
                        "mute",
                        theme,
                        cx,
                    ))
                    .child(self.render_msd_button(
                        "S",
                        soloed,
                        theme.button_solo_active,
                        group_idx,
                        "solo",
                        theme,
                        cx,
                    ))
                    .child(self.render_msd_button(
                        "D",
                        dimmed,
                        theme.button_dim_active,
                        group_idx,
                        "dim",
                        theme,
                        cx,
                    )),
            )
    }

    /// Render M/S/D button (interactive)
    pub fn render_msd_button(
        &self,
        label: &'static str,
        active: bool,
        active_color: gpui::Rgba,
        group_idx: usize,
        button_type: &'static str,
        theme: &Theme,
        cx: &mut Context<Self>,
    ) -> impl IntoElement {
        let d = Ds::from_cx(cx);
        let theme_c = theme.clone();
        div()
            .id((button_type, group_idx))
            .px(spacing::XS)
            .py(spacing::XS)
            .rounded(d.r_sm)
            .text_size(d.text_xs)
            .cursor_pointer()
            .when(active, |d| {
                d.bg(active_color).text_color(theme_c.text_primary)
            })
            .when(!active, |d| {
                d.bg(theme_c.surface)
                    .text_color(theme_c.text_muted)
                    .hover(|style| style.bg(theme_c.surface_hover))
            })
            .on_mouse_up(
                MouseButton::Left,
                cx.listener(move |view, _: &MouseUpEvent, _window, cx| {
                    view.state.update(cx, |state, _cx| {
                        if group_idx < state.app.level_meters.groups.len() {
                            match button_type {
                                "mute" => {
                                    let new_state = !state.app.level_meters.groups[group_idx].muted;
                                    state.app.set_level_meter_mute(group_idx, new_state);
                                }
                                "solo" => {
                                    let new_state =
                                        !state.app.level_meters.groups[group_idx].soloed;
                                    state.app.set_level_meter_solo(group_idx, new_state);
                                }
                                "dim" => {
                                    let new_state =
                                        !state.app.level_meters.groups[group_idx].dimmed;
                                    state.app.set_level_meter_dim(group_idx, new_state);
                                }
                                _ => {}
                            }
                        }
                    });
                    cx.notify();
                }),
            )
            .child(label)
    }

    /// Render separate Meters panel (for queue screen)
    pub fn render_meters_panel(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let d = Ds::from_cx(cx);
        // Extract all data from state first to avoid borrow issues
        let (theme, loudness, groups, selected_group, peak_hold) = {
            let state = self.state.read(cx);
            (
                state.app.ui_state.theme.clone(),
                state.app.playback.loudness_info.clone(),
                state.app.level_meters.groups.clone(),
                state.app.level_meters.selected_group,
                state.app.level_meters.peak_hold.clone(),
            )
        };
        div()
            .flex()
            .flex_col()
            .items_center()
            .size_full()
            .p(d.pad_x)
            .bg(theme.background)
            .child(
                div().w_full().mb(d.gap).child(
                    div()
                        .text_size(d.text_sm)
                        .font_weight(FontWeight::SEMIBOLD)
                        .text_align(TextAlign::Center)
                        .child("Level Meters"),
                ),
            )
            .child({
                // Use a for loop to avoid FnMut closure escape issues with cx
                let mut meter_elements = Vec::new();

                // Left Legend
                meter_elements.push(
                    self.render_vertical_legend(&d, &theme, false)
                        .into_any_element(),
                );

                for (idx, group) in groups.iter().enumerate() {
                    let is_selected = idx == selected_group;
                    meter_elements.push(
                        self.render_meter_group(
                            group,
                            idx,
                            is_selected,
                            loudness.as_ref(),
                            &peak_hold,
                            &theme,
                            cx,
                        )
                        .into_any_element(),
                    );
                }

                // Right Legend
                meter_elements.push(
                    self.render_vertical_legend(&d, &theme, true)
                        .into_any_element(),
                );

                div()
                    .id("meter-groups-scroll")
                    .flex()
                    .flex_1()
                    .justify_center()
                    .gap_0()
                    .overflow_x_scroll()
                    .min_h(rems(18.75))
                    .children(meter_elements)
            })
    }

    /// Render unified meter bar with consistent styling
    /// Uses the TickConfig's scale for bar fill to match tick mark positions
    pub fn render_meter_bar(
        d: &Ds,
        label: &str,
        value: f64,
        tick_config: &TickConfig,
        meter_theme: &MeterTheme,
    ) -> impl IntoElement {
        let horizontal_theme = meter_theme.to_horizontal_meter_theme(d.text_xs, spacing::SM);
        render_horizontal_meter_bar(label.to_string(), value, tick_config, horizontal_theme)
    }

    /// Render stereo width bar (0 = mono, 1 = wide)
    /// Uses the TickConfig's scale for bar fill to match tick mark positions
    pub fn render_width_bar(
        d: &Ds,
        width: f64,
        tick_config: &TickConfig,
        meter_theme: &MeterTheme,
    ) -> impl IntoElement {
        let horizontal_theme = meter_theme.to_horizontal_meter_theme(d.text_xs, spacing::SM);
        let ratio = tick_config.value_to_position(width);
        render_horizontal_meter_bar_with(
            "W",
            ratio,
            meter_theme.color_info,
            format!("{:.0}%", width * 100.0),
            horizontal_theme,
        )
    }

    /// Render multichannel peak spread bar (0 = even, higher = wider channel imbalance)
    pub fn render_peak_spread_bar(
        d: &Ds,
        spread_db: f64,
        tick_config: &TickConfig,
        meter_theme: &MeterTheme,
    ) -> impl IntoElement {
        let horizontal_theme = meter_theme.to_horizontal_meter_theme(d.text_xs, spacing::SM);
        let ratio = tick_config.value_to_position(spread_db);
        render_horizontal_meter_bar_with(
            "D",
            ratio,
            meter_theme.color_info,
            format!("{spread_db:.1} dB"),
            horizontal_theme,
        )
    }

    /// Render LUFS display with True Peak bars at top (wrapper method)
    pub fn render_lufs_with_true_peak(
        &self,
        d: &Ds,
        loudness: Option<&sotf_audio_player::LoudnessData>,
        theme: &Theme,
    ) -> impl IntoElement {
        // Call the standalone function
        render_lufs_with_true_peak(d, loudness, theme)
    }

    /// Render separate LUFS panel
    pub fn render_lufs_panel(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let d = Ds::from_cx(cx);
        let (theme, loudness) = {
            let state = self.state.read(cx);
            (
                state.app.ui_state.theme.clone(),
                state.app.playback.loudness_info.clone(),
            )
        };
        // No `.items_center()` here: cross-axis alignment defaults to
        // stretch so the inner content fills the panel width. With
        // items_center, gpui's flex implementation would size children
        // to their intrinsic content width and `w_full()` on the inner
        // wrapper would not propagate — bars would collapse to ~150px
        // even on a 700px panel.
        div()
            .flex()
            .flex_col()
            .w_full()
            .p(d.card)
            .bg(theme.background)
            .child(self.render_lufs_with_true_peak(&d, loudness.as_ref(), &theme))
    }
}

